from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict, create_dict_with_key


class CellStatsFailure(Exception):
    """
    Exception class for cell_stats
    """
    pass


class CellStats(EgateCommandBase):
    """
    Parser for cell_stats command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(CellStats, self).__init__()
        self.command = 'cell_stats'
        self.params = params
        self.executed_phrase = r'.*?eNB\-\d+\scell\-\d+.*?EGATE>'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))
        self.parsers = {
            'dl_control': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'ul_control': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'dl_data': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'ul_data': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'dl_data_pdcp': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'ul_data_pdcp': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'dl_harq': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'ul_harq': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'dl_proxy_proto': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'ul_proxy_proto': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'phy': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'sch': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'drx': self._parse_with_enb_cell_type_and_scell_key_parameter,
            'ue_failure': self._parse_with_enb_cell_type_and_scell_key_parameter,

            'dl_data_l3': self._parse_with_enb_cell_type_and_scell_key_traffic,
            'ul_data_l3': self._parse_with_enb_cell_type_and_scell_key_traffic,

            'dl_mac': self._parse_with_enb_cell_type_and_scell_key_column_keys,
            'ul_mac': self._parse_with_enb_cell_type_and_scell_key_column_keys,
            'dl_rlc': self._parse_with_enb_cell_type_and_scell_key_column_keys,
            'ul_rlc': self._parse_with_enb_cell_type_and_scell_key_column_keys,
            'pusch': self._parse_with_enb_cell_type_and_scell_key_column_keys,

            'pdsch': self._parse_with_enb_cell_type_and_scell_key_scell,

            'cpu_util': self._parse_with_enb_cell_type_and_scell_key_dsp_chip,
            'dl_beam': self._parse_with_enb_cell_type_and_scell_key_beam_id,

            'enb_tx_power': self._parse_with_enb_cell_type_and_scell_key_subframe,

            'dl_energy_meas': '',
            'all': '',
            'ue_counters': ''
        }

    def execute(self, egate_id=0):
        """
        Execute egate cmd.
        :return: parsed output
        """
        if 'clear' not in list(self.params.keys()):
            raise CellStatsFailure("Use execute_and_parse() method to parse output of {} cmd".format(self.command))
        else:
            self.executed_phrase = r'.*?EGATE>'
            status, output = super(CellStats, self).execute(egate_id=egate_id, command=self.to_execute)
            if status:
                return status, output
            else:
                raise CellStatsFailure(output)

    def execute_and_parse(self, egate_id=0):
        """

        :return:
        """
        if 'clear' not in list(self.params.keys()):
            status, output = super(CellStats, self).execute(egate_id=egate_id, command=self.to_execute)
            if status:
                parsed_output = self._parse_cells_stats_output(output)
                logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
                return parsed_output
        else:
            raise CellStatsFailure("Use execute() method to execute {} cmd with clear param".format(self.command))

    def _build_command(self):
        """
        Build cell_stats command.
        :return: None
        """
        for param, value in list(self.params.items()):
            if param in ['display', 'clear', 'chcek']:
                self.to_execute += ' {}'.format(param)
            else:
                self.to_execute += ' {}={}'.format(param, value)

    def _parse_cells_stats_output(self, output):
        try:
            stats_type = self.params['type']
            return self.parsers[stats_type](output)
        except KeyError:
            return self._parse_with_enb_cell_type_and_scell_key_parameter(output)

    def _parse_with_enb_cell_type_and_scell_key_parameter(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='Parameter', list_of_output_parsed_lines=output)

    def _parse_with_enb_cell_type_and_scell_key_traffic(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='Traffic', list_of_output_parsed_lines=output)

    def _parse_with_enb_cell_type_and_scell_key_column_keys(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict(list_of_output_parsed_lines=output)

    def _parse_with_enb_cell_type_and_scell_key_scell(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='SCell', list_of_output_parsed_lines=output)

    def _parse_with_enb_cell_type_and_scell_key_dsp_chip(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='DSP Chip', list_of_output_parsed_lines=output)

    def _parse_with_enb_cell_type_and_scell_key_beam_id(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)

        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='Beam Id', list_of_output_parsed_lines=output)

    def _parse_with_enb_cell_type_and_scell_key_subframe(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()

        return create_dict_with_key(key='Subframe', list_of_output_parsed_lines=output)

    def _parser_not_supported(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        return "Parser not implemented for give output:\n{}".format(cmd_output)
